.db.s1 .dbl{border-color:#d9453d}.db.s2 .dbl{border-color:#e0b040}.db.s3 .dbl{border-color:#5cc05a}.db.s4 .dbl{border-color:#f2c14e;color:#f2c14e}
.dbz{position:absolute;left:14%;bottom:58%;font:16px var(--fl);color:#cfe0ff;z-index:4;animation:zk 3s linear infinite;animation-delay:var(--l,0s)}
.dbfx u{position:absolute;width:6px;height:6px;background:#ffe96b;box-shadow:0 0 6px 2px #ffe96b88;z-index:4;animation:dbsp 1.2s steps(6) infinite}@keyframes dbsp{0%{opacity:0;transform:scale(.3)}30%{opacity:1}100%{opacity:0;transform:translate(10px,-26px) scale(1.4)}}

.cnbub{position:absolute;left:62%;top:42%;width:150px;height:150px;margin:-75px 0 0 -75px;border-radius:50%;background:radial-gradient(circle at 35% 35%,rgba(255,255,255,.55),rgba(140,200,255,.35) 45%,rgba(90,120,255,.18) 70%);border:3px solid rgba(200,230,255,.85);box-shadow:0 0 30px rgba(140,200,255,.5);z-index:4;display:grid;place-items:center;transform:scale(.45);transition:transform 6s ease-in-out}
.cnbub.in{transform:scale(1);transition-duration:4s}.cnbub span{font:10px var(--fh);color:#fff;text-shadow:2px 2px 0 #14204f}
.cslog{max-height:340px;overflow-y:auto;display:flex;flex-direction:column;gap:8px;padding:4px 2px;margin-bottom:8px}
.csm{padding:8px 10px;border:3px solid var(--ln);max-width:88%;font-size:14px;line-height:1.5;overflow-wrap:anywhere}.csm b{display:block;font:7px var(--fh);margin-bottom:3px;opacity:.85}
.csm.a{background:#2a2350;color:#f6edcf;align-self:flex-start}.csm.u{background:var(--p2);align-self:flex-end}.csm.sys{background:transparent;border-style:dashed;font-size:12px;color:var(--mut);align-self:center}.csm.typing{animation:cstp 1s steps(2) infinite alternate}@keyframes cstp{to{opacity:.5}}

